{"action":"run","command":"node - <<'NODE'
const assert = require('node:assert/strict');
(async () => {
  for (const [path, title, description, heading, nav] of [
    ['/', 'Home Page', 'Welcome to our Next.js app', 'Home', '/about'],
    ['/about', 'About Us', 'Learn more about us', 'About', '/'],
  ]) {
    const response = await fetch(`http://127.0.0.1:3107${path}`);
    assert.equal(response.status, 200, `${path} status`);
    const html = await response.text();
    for (const [label, pattern] of [
      ['title', `<title>${title}</title>`],
      ['description', `content="${description}"`],
      ['heading', `<h1>${heading}</h1>`],
      ['nav', `href="${nav}"`],
      ['contact', 'href="/contact"'],
      ['language', '<html lang="en"'],
    ]) assert.ok(html.includes(pattern), `${path} missing ${label}`);
    console.log(`${path}: 200; title, description, heading, links and document language OK`);
  }
})().catch(error => { console.error(error); process.exitCode = 1 });
NODE","cwd":"/workspace"}

